    private static String goalMinutes(Vector v,ci p){StringBuilder b=new StringBuilder();for(int i=0;i+1<v.size();i+=2)if(v.elementAt(i)==p){if(b.length()>0)b.append(',');b.append(minute(v.elementAt(i+1)));}return b.toString();}
    private static int points(int gf,int ga){return gf>ga?3:gf==ga?1:0;}
    private static int hash(int x){x^=x>>>16;x*=0x7feb352d;x^=x>>>15;x*=0x846ca68b;x^=x>>>16;return x&0x7fffffff;}
    private static int mod(int x,int n){return n<=0?0:hash(x)%n;}
    private static int clamp(int x,int lo,int hi){return Math.max(lo,Math.min(hi,x));}
    private static int spread(int seed,int radius){return mod(seed,2*radius+1)-radius;}
    private static String[] grow(String[] p,int n){if(p.length>=n)return p;String[] x=new String[n];System.arraycopy(p,0,x,0,p.length);for(int i=p.length;i<n;i++)x[i]="";return x;}

    /** side,index,id,number,name,pos,starter,minutes */
    private static ArrayList<String[]> participants(dw team,int side,int round){ArrayList<String[]> out=new ArrayList<String[]>();int count=0;try{count=Math.min(25,pfmRosterAccess50.count(team));}catch(Throwable ignored){}for(int i=0;i<count;i++)try{ci p=cp.a(team,i);if(p==null)continue;int mins=pfmCondition60.minutesForRosterIndex(team,i,round);boolean starter=i<11;if(!starter&&mins<=0)continue;if(starter&&mins<=0)mins=90;out.add(new String[]{String.valueOf(side),String.valueOf(i),String.valueOf(id(p)),String.valueOf(ub(p,"f")),playerName(p),pos(p),starter?"1":"0",String.valueOf(mins)});}catch(Throwable ignored){}return out;}
    private static int startMinute(String[] p){try{return "1".equals(p[5])?1:Math.max(1,91-Integer.parseInt(p[6]));}catch(Throwable ignored){return 1;}}
    private static int endMinute(String[] p){try{return "1".equals(p[5])?Math.min(90,Integer.parseInt(p[6])):90;}catch(Throwable ignored){return 90;}}
    private static boolean activeAt(String[] p,int minute){return minute>=startMinute(p)&&minute<=endMinute(p);}
    private static boolean rawActiveAt(String[] p,int minute){try{int mins=Integer.parseInt(p[7]);return "1".equals(p[6])?minute<=mins:minute>=Math.max(1,91-mins);}catch(Throwable ignored){return false;}}
    private static int eventMax(String[] p){int max=startMinute(p);for(int col=8;col<=12&&col<p.length;col++)for(String s:p[col].split(","))try{max=Math.max(max,Integer.parseInt(s));}catch(Throwable ignored){}return max;}
    private static int weight(String[] p,int kind){String po=p[4];ci x=null;try{x=player(Integer.parseInt(p[10]));}catch(Throwable ignored){}int quality=x==null?70:(ub(x,"c")+ub(x,"d")+ub(x,"e"))/3;if(kind==0){if("GK".equals(po))return 0;return ("DEF".equals(po)?7:"MID".equals(po)?25:65)+quality/12;}if(kind==1){return ("GK".equals(po)?1:"DEF".equals(po)?16:"MID".equals(po)?50:34)+quality/15;}if("GK".equals(po))return 0;return ("DEF".equals(po)?44:"MID".equals(po)?39:27)+quality/20;}
    private static String[] pick(ArrayList<String[]> ps,int side,int minute,int excluded,int kind,int seed,boolean fullMatch){int total=0;for(String[] p:ps)try{if(!"P".equals(p[0])||Integer.parseInt(p[1])!=side||Integer.parseInt(p[10])==excluded||!activeAt(p,minute)||(fullMatch&&Integer.parseInt(p[6])<85))continue;total+=weight(p,kind);}catch(Throwable ignored){}if(total<=0&&fullMatch)return pick(ps,side,minute,excluded,kind,seed,false);if(total<=0)return null;int roll=mod(seed,total);for(String[] p:ps)try{if(!"P".equals(p[0])||Integer.parseInt(p[1])!=side||Integer.parseInt(p[10])==excluded||!activeAt(p,minute)||(fullMatch&&Integer.parseInt(p[6])<85))continue;roll-=weight(p,kind);if(roll<0)return p;}catch(Throwable ignored){}return null;}
    private static void normalizeGoals(Vector goals,ArrayList<String[]> rows,int side,int round,int seed){for(int i=0;i+1<goals.size();i+=2)try{ci scorer=(ci)goals.elementAt(i);int pid=id(scorer),m=minuteInt(goals.elementAt(i+1));String[] current=null;for(String[] p:rows)if(Integer.parseInt(p[2])==pid){current=p;break;}if(current!=null&&rawActiveAt(current,m))continue;ArrayList<String[]> archiveRows=new ArrayList<String[]>();for(String[] p:rows)archiveRows.add(new String[]{"P",String.valueOf(side),p[3],p[4],p[5],p[6],p[7],"65","","",p[2],"",""});String[] replacement=pick(archiveRows,side,m,-1,0,seed+round*977+i*131,false);if(replacement!=null){ci chosen=player(Integer.parseInt(replacement[10]));if(chosen!=null)goals.setElementAt(chosen,i);}}catch(Throwable ignored){}}
    private static void appendTeam(StringBuilder out,ArrayList<String[]> ps,Vector goals,int gf,int ga,int round){for(String[] x:ps)try{int pid=Integer.parseInt(x[2]);ci p=player(pid);int pg=goalsFor(goals,p),rating=pfmPatch36.buildRating(p,points(gf,ga),gf,ga,pg,pid,round);out.append("P\t").append(x[0]).append('\t').append(x[3]).append('\t').append(x[4]).append('\t').append(x[5]).append('\t').append(x[6]).append('\t').append(x[7]).append('\t').append(rating).append('\t').append(goalMinutes(goals,p)).append("\t\t").append(pid).append("\t\t\n");}catch(Throwable ignored){}}
    private static void appendSubs(StringBuilder out,ArrayList<String[]> ps,int side){ArrayList<String[]> outs=new ArrayList<String[]>(),ins=new ArrayList<String[]>();for(String[] p:ps){int m=Integer.parseInt(p[7]);if("1".equals(p[6])&&m<90)outs.add(p);if("0".equals(p[6])&&m>0)ins.add(p);}boolean[] used=new boolean[ins.size()];for(String[] o:outs){int om=Integer.parseInt(o[7]),best=-1;for(int i=0;i<ins.size();i++)if(!used[i]&&ins.get(i)[5].equals(o[5])&&90-Integer.parseInt(ins.get(i)[7])==om){best=i;break;}if(best<0)for(int i=0;i<ins.size();i++)if(!used[i]&&90-Integer.parseInt(ins.get(i)[7])==om){best=i;break;}if(best>=0){used[best]=true;String[] in=ins.get(best);out.append("S\t").append(side).append('\t').append(om).append('\t').append(o[4]).append('\t').append(in[4]).append('\t').append(o[2]).append('\t').append(in[2]).append('\n');}}}
    private static int strength(dw t){int sum=0,n=0;try{for(int i=0;i<11;i++){ci p=cp.a(t,i);if(p!=null){sum+=ub(p,"c")+ub(p,"d")+ub(p,"e");n+=3;}}}catch(Throwable ignored){}return n==0?70:sum/n;}

    /** One latent match flow drives possession, attempts, corners, fouls and offsides. */
    private static void appendStats(StringBuilder out,dw h,dw a,int hg,int ag,int round){int hs=strength(h),as=strength(a),seed=teamId(h)*1009+teamId(a)*719+round*313;int control=(hs-as)*2/3+3+spread(seed+1,15)+spread(seed+2,7);int hp=clamp(50+control,28,72),ap=100-hp;int tempo=spread(seed+3,4);int hsh=clamp(Math.max(hg,9+(hp-50)/2+(hs-70)/8+tempo+spread(seed+4,5)+hg),Math.max(1,hg),30);int ash=clamp(Math.max(ag,9+(ap-50)/2+(as-70)/8+tempo+spread(seed+5,5)+ag),Math.max(1,ag),30);int hst=clamp(hg+(hsh-hg)*(24+mod(seed+6,18))/100,hg,hsh),ast=clamp(ag+(ash-ag)*(24+mod(seed+7,18))/100,ag,ash);int hc=clamp((hsh+1)/3+(hp-50)/9+spread(seed+8,3),0,15),ac=clamp((ash+1)/3+(ap-50)/9+spread(seed+9,3),0,15);int hf=clamp(11+(50-hp)/8+spread(seed+10,6),5,23),af=clamp(11+(50-ap)/8+spread(seed+11,6),5,23);int ho=clamp(hsh/6+spread(seed+12,2),0,7),ao=clamp(ash/6+spread(seed+13,2),0,7);out.append("M\t").append(hp).append('\t').append(ap).append('\t').append(hsh).append('\t').append(ash).append('\t').append(hst).append('\t').append(ast).append('\t').append(hc).append('\t').append(ac).append('\t').append(hf).append('\t').append(af).append('\t').append(ho).append('\t').append(ao).append("\t0\t0\t0\t0\n");}

    /** Preserve the result, but repair impossible scorers before the stock ledgers consume it. */
    public static void finish(dw home,dw away,Vector[] events){int round=roundOne();ArrayList<String[]> hp=participants(home,0,round),ap=participants(away,1,round);try{normalizeGoals(events[0],hp,0,round,teamId(home)*1709+teamId(away)*1013);normalizeGoals(events[1],ap,1,round,teamId(away)*1709+teamId(home)*1013);}catch(Throwable ignored){}try{Method m=ca.class.getDeclaredMethod("a",dw.class,dw.class,Vector[].class);m.setAccessible(true);m.invoke(null,home,away,events);}catch(Throwable fatal){return;}try{int hg=events[0].size()/2,ag=events[1].size()/2;StringBuilder out=new StringBuilder();out.append("H\t").append(teamName(home)).append('\t').append(teamName(away)).append('\t').append(hg).append('\t').append(ag).append('\n');for(int side=0;side<2;side++)for(int i=0;i+1<events[side].size();i+=2){ci scorer=(ci)events[side].elementAt(i);out.append("G\t").append(side).append('\t').append(minute(events[side].elementAt(i+1))).append('\t').append(playerName(scorer)).append("\t\t").append(id(scorer)).append('\n');}appendSubs(out,hp,0);appendSubs(out,ap,1);appendStats(out,home,away,hg,ag,round);appendTeam(out,hp,events[0],hg,ag,round);appendTeam(out,ap,events[1],ag,hg,round);prefs().edit().putString(key(round,home,away),out.toString()).commit();}catch(Throwable ignored){}}

    private static byte[] bytes(Class<?> c,String name){try{byte[] b=(byte[])f(c,name,byte[].class).get(null);return b==null?new byte[0]:(byte[])b.clone();}catch(Throwable x){return new byte[0];}}
