    /** Replace the stock roster-wide assist draw with a goal-minute eligible draw. */
    public static void applyAssists(byte[] before,byte[] after,int round){try{byte[] live=liveBytes(pfmContrib80.class,"assists");int[] stock=new int[Math.max(before.length,after.length)];for(int i=0;i<stock.length;i++){stock[i]=delta(before,after,i);if(stock[i]>0&&i<live.length)live[i]=(byte)(i<before.length?(before[i]&255):0);}SharedPreferences.Editor edit=prefs().edit();for(Map.Entry<String,?> e:prefs().getAll().entrySet()){if(!e.getKey().startsWith(prefix(round))||!(e.getValue() instanceof String))continue;ArrayList<String[]> ps=parse((String)e.getValue());for(int side=0;side<2;side++){int quota=0;ArrayList<String[]> goals=new ArrayList<String[]>();for(String[] p:ps)try{if("P".equals(p[0])&&Integer.parseInt(p[1])==side)quota+=stock[Integer.parseInt(p[10])];else if("G".equals(p[0])&&Integer.parseInt(p[1])==side)goals.add(p);}catch(Throwable ignored){}for(int gi=0;gi<goals.size()&&quota>0;gi++){String[] g=goals.get(gi);int scorer=Integer.parseInt(g[5]),m=Integer.parseInt(g[2]);String[] chosen=pick(ps,side,m,scorer,1,round*7919+side*997+gi*313,false);if(chosen==null)continue;int pid=Integer.parseInt(chosen[10]);if(pid>=0&&pid<live.length&&(live[pid]&255)<255){live[pid]=(byte)((live[pid]&255)+1);g[4]=chosen[3];addMinute(chosen,9,m);int applied=rate(chosen,4);pfmRatingPost36.adjust(pid,applied);quota--;}}}edit.putString(e.getKey(),serialize(ps));}edit.commit();save(pfmContrib80.class);}catch(Throwable ignored){}}

    private static void moveOne(byte[] live,int from,int to){if(from==to||from<0||to<0||from>=live.length||to>=live.length)return;if((live[from]&255)>0)live[from]=(byte)((live[from]&255)-1);if((live[to]&255)<255)live[to]=(byte)((live[to]&255)+1);}
    private static int cardMinute(String[] p,int seed,boolean red){int lo=startMinute(p),hi=endMinute(p);if("GK".equals(p[4]))lo=Math.max(lo,72);if(red)lo=Math.max(lo,eventMax(p));if(lo>hi)lo=hi;return lo+mod(seed,Math.max(1,hi-lo+1));}
    private static void redFlow(String[] m,int[] earliest){try{int hp=Integer.parseInt(m[1]),hs=Integer.parseInt(m[3]),as=Integer.parseInt(m[4]),hst=Integer.parseInt(m[5]),ast=Integer.parseInt(m[6]),hc=Integer.parseInt(m[7]),ac=Integer.parseInt(m[8]);int homeLoss=earliest[0]>0?clamp((90-earliest[0])/10,1,8):0,awayLoss=earliest[1]>0?clamp((90-earliest[1])/10,1,8):0,shift=awayLoss-homeLoss;hp=clamp(hp+shift,25,75);m[1]=String.valueOf(hp);m[2]=String.valueOf(100-hp);hs=clamp(hs+shift/2,1,30);as=clamp(as-shift/2,1,30);m[3]=String.valueOf(hs);m[4]=String.valueOf(as);m[5]=String.valueOf(clamp(hst,0,hs));m[6]=String.valueOf(clamp(ast,0,as));m[7]=String.valueOf(clamp(hc+shift/3,0,15));m[8]=String.valueOf(clamp(ac-shift/3,0,15));}catch(Throwable ignored){}}

    /** Give cards coherent owners/minutes; a red card closes the player's interval. */
    public static void applyCards(byte[] y0,byte[] y1,byte[] r0,byte[] r1,byte[] s0,byte[] s1,int round){try{byte[] yl=liveBytes(pfmDiscipline70.class,"yellow"),rl=liveBytes(pfmDiscipline70.class,"red"),sl=liveBytes(pfmDiscipline70.class,"suspension");SharedPreferences.Editor edit=prefs().edit();for(Map.Entry<String,?> e:prefs().getAll().entrySet()){if(!e.getKey().startsWith(prefix(round))||!(e.getValue() instanceof String))continue;ArrayList<String[]> ps=parse((String)e.getValue());int[] counts=new int[4],earliest={0,0};for(int i=0;i<ps.size();i++){String[] source=ps.get(i);if(source.length<11||!"P".equals(source[0]))continue;source=grow(source,13);ps.set(i,source);int side=Integer.parseInt(source[1]),pid=Integer.parseInt(source[10]),dy=delta(y0,y1,pid),dr=delta(r0,r1,pid);for(int n=0;n<dy;n++){String[] target=source;if("GK".equals(source[4])&&mod(pid*131+round*719+n*97,100)<88){String[] x=pick(ps,side,75,pid,2,pid*313+round*997+n,false);if(x!=null)target=x;}int tid=Integer.parseInt(target[10]);if(tid!=pid){moveOne(yl,pid,tid);if(pid<s0.length&&pid<s1.length&&tid<sl.length&&(s1[pid]&255)>(s0[pid]&255)){sl[pid]=(byte)(s0[pid]&255);if((yl[tid]&255)%5==0)sl[tid]=(byte)Math.max(sl[tid]&255,1);}}int cm=cardMinute(target,pid*131+round*719+n*97,false);addMinute(target,11,cm);counts[side]++;int applied=rate(target,-2);pfmRatingPost36.adjust(tid,applied);}for(int n=0;n<dr;n++){String[] target=source;if("GK".equals(source[4])||Integer.parseInt(source[6])<85){String[] x=pick(ps,side,60,pid,2,pid*173+round*977+n*101,true);if(x!=null)target=x;}int tid=Integer.parseInt(target[10]);if(tid!=pid){moveOne(rl,pid,tid);if(pid<s0.length&&pid<s1.length&&tid<sl.length){int ban=Math.max(1,(s1[pid]&255)-(s0[pid]&255));sl[pid]=(byte)(s0[pid]&255);sl[tid]=(byte)Math.max(sl[tid]&255,ban);}}int cm=cardMinute(target,pid*173+round*977+n*101,true);addMinute(target,12,cm);int played="1".equals(target[5])?cm:Math.max(1,cm-startMinute(target)+1);target[6]=String.valueOf(Math.min(Integer.parseInt(target[6]),played));counts[2+side]++;if(earliest[side]==0||cm<earliest[side])earliest[side]=cm;int applied=rate(target,-7);pfmRatingPost36.adjust(tid,applied);}}for(int i=0;i<ps.size();i++){String[] p=ps.get(i);if("M".equals(p[0])){p=grow(p,17);p[13]=String.valueOf(counts[0]);p[14]=String.valueOf(counts[1]);p[15]=String.valueOf(counts[2]);p[16]=String.valueOf(counts[3]);redFlow(p,earliest);ps.set(i,p);}}edit.putString(e.getKey(),serialize(ps));}edit.commit();save(pfmDiscipline70.class);}catch(Throwable ignored){}}
